// Typ vozidla (druh z registru) → kategorie pro statistiky a filtry. NENÍ to park.
export const vehicleTypeCat = (druh) => {
  const d = String(druh || '').toLowerCase()
  if (d.includes('motocykl')) return 'Motocykly'
  if (d.includes('tahač')) return 'Tahače' // „tahač návěsů" obsahuje i „návěs" → kontrolovat dřív
  if (d.includes('návěs')) return 'Návěsy'
  if (d.includes('autobus')) return 'Autobusy'
  if (d.includes('přívěs')) return 'Přívěsy' // „přívěs nákladní" obsahuje i „nákladní" → kontrolovat dřív
  if (d.includes('nákladní')) return 'Nákladní vozidla'
  if (d.includes('traktor') || d.includes('stroj') || d.includes('malotraktor')) return 'Traktory a stroje'
  return 'Osobní vozidla'
}
export const vehicleTypeOrder = ['Osobní vozidla', 'Motocykly', 'Autobusy', 'Tahače', 'Návěsy', 'Nákladní vozidla', 'Přívěsy', 'Traktory a stroje']

// --- STK a dálniční známka (ukázková data; na BE: STK z registru vozidel, známka z eDalnice.cz) ---
// Veřejné CORS API jako u ARES neexistuje → na produkci přes B2B API / server-side ověření.
const _vseed = (id) => parseInt(String(id).replace(/\D/g, '') || '1', 10)
const _fmtD = (d) => `${d.getDate()}. ${d.getMonth() + 1}. ${d.getFullYear()}`
export const vehicleStk = (v) => {
  // STK platí 2 roky → většina v budoucnu, pár končících/prošlých (vůči dnešku)
  const d = new Date(); d.setHours(0, 0, 0, 0)
  d.setDate(d.getDate() + ((_vseed(v.id) * 37) % 760) - 30) // -30 .. +729 dní
  return _fmtD(d)
}
export const vehicleVignette = (v) => {
  // dálniční známku má jen vozidlo do 3,5 t (osobní, užitkové, speciální); motocykl ne, nad 3,5 t platí mýto
  if (!/osobní|speciální|do 3,5/.test(v.druh || '')) return null
  const s = _vseed(v.id)
  const d = new Date(); d.setHours(0, 0, 0, 0)
  d.setDate(d.getDate() + ((s * 53) % 430) - 40) // -40 .. +389 dní
  return { country: 'CZ', type: ['roční', 'roční', '30denní', '10denní'][s % 4], validTo: _fmtD(d) }
}

