// ======================================================================
// TCO ENGINE — deterministický odhad ročních PROVOZNÍCH nákladů vozidla.
// Modelový výpočet z typu, stáří, paliva a odhadu nájezdu. Pojistné NENÍ
// součástí (doplní je napojení na pojišťovnu). Slouží pro Reporting a
// majitelský pohled. Po napojení telematiky/účetnictví nahradí reálná data.
// ======================================================================
const _crng = (seed) => { let t = seed + 0x6D2B79F5; return () => { t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296 } }
const THIS_YEAR = 2026

// základní parametry podle kategorie vozidla
const COST_PROFILE = {
  'Autobusy':           { km: 56000, kmVar: 22000, l100: 36, pneu: 0.55, servis: 2.4, tollKm: 0,    tollFix: 4800 },
  'Nákladní vozidla':   { km: 22000, kmVar: 9000,  l100: 11, pneu: 0.18, servis: 1.5, tollKm: 0,    tollFix: 1500 },
  'Tahače':             { km: 98000, kmVar: 34000, l100: 32, pneu: 0.70, servis: 2.0, tollKm: 2.4,  tollFix: 1500 },
  'Návěsy':             { km: 0,     kmVar: 0,     l100: 0,  pneu: 0.00, servis: 0.6, tollKm: 0,    tollFix: 0 },
  'Přívěsy':            { km: 0,     kmVar: 0,     l100: 0,  pneu: 0.00, servis: 0.4, tollKm: 0,    tollFix: 0 },
  'Osobní vozidla':     { km: 24000, kmVar: 12000, l100: 7.4, pneu: 0.22, servis: 1.3, tollKm: 0,   tollFix: 2300 },
  'Traktory a stroje':  { km: 9000,  kmVar: 4000,  l100: 14, pneu: 0.30, servis: 2.6, tollKm: 0,    tollFix: 0 },
  'Motocykly':          { km: 6000,  kmVar: 3000,  l100: 4.5, pneu: 0.20, servis: 0.9, tollKm: 0,   tollFix: 900 },
}
const FUEL_COST_MULT = { 'Diesel': 1, 'Benzín': 1.05, 'CNG': 0.74, 'LPG': 0.62, 'Elektro': 0.32, 'ZP': 0.74, 'NM': 1 }

export const vehicleAnnualCost = (v) => {
  const cat = vehicleTypeCat(v.druh)
  const p = COST_PROFILE[cat] || COST_PROFILE['Osobní vozidla']
  const rng = _crng(_vseed(v.id) * 2654435761 % 4294967296)
  const age = Math.max(0, THIS_YEAR - (v.year || THIS_YEAR))
  const km = Math.round((p.km + (rng() - 0.5) * 2 * p.kmVar) / 100) * 100
  const kmPos = Math.max(0, km)
  // palivo — spotřeba roste se stářím, cena dle druhu paliva
  const fuelMult = FUEL_COST_MULT[v.fuel] || 1
  const consAge = p.l100 * (1 + Math.min(age, 25) * 0.008)
  const phm = Math.round((kmPos / 100) * consAge * NAFTA_CZK * fuelMult)
  // servis roste se stářím (staré vozy = vyšší náklady na údržbu)
  const ageFactor = 1 + Math.min(age, 28) * 0.055 + (rng() - 0.5) * 0.2
  const servis = Math.round(kmPos * p.servis * Math.max(0.6, ageFactor))
  const pneu = Math.round(kmPos * p.pneu * (0.85 + rng() * 0.3))
  const dalnice = Math.round(kmPos * p.tollKm + p.tollFix)
  const pokuty = rng() < 0.18 ? Math.round((1 + rng() * 9)) * 500 : 0
  const total = phm + servis + pneu + dalnice + pokuty
  return { km: kmPos, phm, servis, pneu, dalnice, pokuty, total, age }
}

// Věková kategorie vozidla pro pyramidu stáří
export const vehicleAgeBand = (v) => {
  const age = Math.max(0, THIS_YEAR - (v.year || THIS_YEAR))
  if (age <= 5) return '0–5 let'
  if (age <= 10) return '6–10 let'
  if (age <= 15) return '11–15 let'
  if (age <= 20) return '16–20 let'
  return '21+ let'
}
export const vehicleAgeBandOrder = ['0–5 let', '6–10 let', '11–15 let', '16–20 let', '21+ let']


